import re

def predict(probe):
    # Remove all whitespace, then insert "Z" at floor(len/2) [E1-E12]
    # Whitespace includes space, tab, newline, CR [E4, E12]
    outputs = []
    for s in probe["inputs"]:
        cleaned = re.sub(r'\s', '', s)
        pos = len(cleaned) // 2
        outputs.append(cleaned[:pos] + "Z" + cleaned[pos:])
    return {"outputs": outputs}
